          <path clip-rule="evenodd" d="M0.869934 647C5.21619 642.99 9.48983 638.885 13.6876 634.688C96.4849 551.89 143 439.593 143 322.5C143 205.407 96.485 93.1097 13.6877 10.3124C10.185 6.80975 6.62959 3.37202 3.02321 0L712 0V647H0.869934Z" fill="rgb(4, 64, 38)" fill-rule="evenodd">
