                                'security': '406b83d09a'
                            },
                            beforeSend: function () {
                                jQuery('.loading').addClass('show');
                            },
                            complete: function (response) {
                                response = response.responseJSON;
                                if(response.status)
                                {
                                    var temp = $(product_lightbox);
                                    temp.find('.product-lightbox-content').append(response.php);
                                    $('.site-main').append(temp);
