      <script>
       jQuery(document).ready(function ($) {

                        jQuery('[data-fancybox="galleryimg"]').fancybox({
                            autoSize : true,
                            fitToView : true,
                            animationEffect : 'zoom-in-out',
                            transitionEffect: "fade",
                        });

                        IMGCarousel();
                        function IMGCarousel()
                        {
                            var ieff = new gsap.timeline({paused:true});
                            
                            jQuery('.images-carousel').owlCarousel({
                                nav:true,
                                navText:["<div class='nav-btn prev-nav '><img width='28' height='28' src='https://www.greenfeed.com.vn/thuy-san/wp-content/themes/gf-thuysan/assets/images/green-arrow.svg' alt='Prev'></div>","<div class='nav-btn next-nav '><img width='28' height='28' src='https://www.greenfeed.com.vn/thuy-san/wp-content/themes/gf-thuysan/assets/images/green-arrow.svg' alt='Next'></div>"],
                                dots:false,
                                loop:true,
                                margin:120,
                                smartSpeed:0.00001,
                                responsive:{
                                    0:{
                                        items:1,
                                        nav:true, 
                                        margin:0,
                                    },
                                    1024:{
                                        items:1,
                                        stagePadding:40
                                    }
                                },
                                onInitialized : onInitialized,
                                onTranslated : onTranslated,
                                onTranslate : onTranslate
                            });

                            function onInitialized(e)
                            {   
                                $('.image-item').css('opacity',0);
                                $('.images .owl-nav .next-nav').css('opacity',0);
                                
                            }
                            function onTranslate(e)
                            {   
                            $('.image-item').css('opacity',0);
                            }
                            function onTranslated(e)
                            {   
                                ieff.progress(0).clear();
                                
                                ieff.fromTo($(e.target).find('.owl-item.active').find('.image-item'), {
                                    x:"2rem",
                                    opacity:0,
                                },{
                                    x:0,
                                    opacity:1,
                                    duration: 1.75, 
                                    ease: 'power4.out', 
                                    delay:.5,
                                }, 0);

                            
                                if(!window.matchMedia("(max-width: 1023px)").matches)
                                {
                                    ieff.fromTo($(e.target).find('.owl-item:not(.active)').find('.image-item'), {
                                        x:"2rem",
                                        opacity:0,
                                    
                                    },{
                                        x:0,
                                        opacity:1,
                                        duration: 1.75, 
                                        ease: 'power4.out', 
                                        delay:.5,
                                    }, 0);
                                }
                                
                                ieff.fromTo($('.images .owl-nav .next-nav'), {
                                    opacity:0,
                                   
                                },{
                                    x:0,
                                    opacity:1,
                                    duration: 1.75, 
                                    ease: 'power4.out', 
                                    delay:.5,
                                }, 0);

                                ieff.fromTo($(e.target).find('.owl-item.active').find('.image-box__content-wrap'), {
                                    x:"-2rem",
                                    opacity:0,
                                },{
                                    x:0,
                                    opacity:1,
                                    duration: 1.5, 
                                    ease: 'power3.out', 
                                    delay:.5,
                                }, 1);
                                
                                ieff.timeScale(2).play();
                                
                            }

                            function Playscrollimg()
                            {
                                ieff.fromTo($('.images-carousel').find('.owl-item.active').find('.image-item'), {
                                    x:"2rem",
                                    opacity:0,
                                },{
                                    x:0,
                                    opacity:1,
                                    duration: 1.75, 
                                    ease: 'power4.out', 
                                    delay:.5,
                                }, 0);

                            
                                if(!window.matchMedia("(max-width: 1023px)").matches)
                                {
                                    ieff.fromTo($('.images-carousel').find('.owl-item:not(.active)').find('.image-item'), {
                                        x:"2rem",
                                        opacity:0,
                                    
                                    },{
                                        x:0,
                                        opacity:1,
                                        duration: 1.75, 
                                        ease: 'power4.out', 
                                        delay:.5,
                                    }, 0);

                                }

                                ieff.fromTo($('.images-carousel').find('.owl-item.active').find('.image-box__content-wrap'), {
                                    x:"-2rem",
                                    opacity:0,
                                },{
                                    x:0,
                                    opacity:1,
                                    duration: 1.5, 
                                    ease: 'power3.out', 
                                    delay:.5,
                                }, 1);

                                ieff.fromTo($('.images .owl-nav .next-nav'), {
                                    opacity:0,
                                
                                },{
                                    opacity:1,
                                    duration: 1.75, 
                                    ease: 'power4.out', 
                                    delay:.5,
                                }, 0);

                                ieff.timeScale(2).play();
                            }
                            
                            ScrollTrigger.create({
                                trigger: '.images',
                                start: 'top center',
                                once: true,
                                onEnter: Playscrollimg,
                            });
                            
                        }
                        });
