     <script>
      jQuery(document).ready(function ($) {
                        ExportAni();
                        function ExportAni()
                        {
                            var scrollep = new gsap.timeline({paused:true});
                            gsap.set('.export_locations-item,.export_description', {
                                alpha:0,
                            });

                            const kvs = gsap.utils.toArray('.kvline');
                            kvs.forEach((kv, i) => {
                                
                                scrollep.fromTo(kv, 
                                {
                                    drawSVG:"0%",
                                }, {
                                    duration: 1,
                                    drawSVG:"100%",
                                    delay:(i)*1,
                                    ease: 'power4.out',
                                }, .25);
                            });

                            const blocks = gsap.utils.toArray('.export_locations-item,.export_description');
                            blocks.forEach((block, i) => {
                                
                                scrollep.to(block, {
                                    alpha:1,
                                    duration: .875, 
                                    delay:(i)*1+.5,
                                    ease: 'power4.out', 
                                   
                                }, .25);
                            });
                        
                            function Playscrollep()
                            {
                                scrollep.timeScale(1.25).play();
                            }
                            ScrollTrigger.create({
                                trigger: '.export_locations',
                                onEnter: Playscrollep,
                                start: 'top center',
                            });
                            
                        }

                    });
     </script>
