            function HideStickyScrollEnd()
            {
                const fadeout = gsap.from('.sticky_price_list .sticky_btn-label', { 
                        opacity:0,
                        paused: true,
                        duration: 0.25,
                        ease: 'power2.easeOut',
                });
                fadeout.play();
                ScrollTrigger.create({
                    start: "bottom-=100px bottom",
                    end: "bottom bottom-=100px ",
                    onEnter : () => {
                        fadeout.reverse();
                    },
                    onEnterBack : () => {
                        fadeout.reverse();
                    },
                    onLeave : () => {
                        fadeout.play();
                    },
                    onLeaveBack : () => {
                        fadeout.play();
                    },
                });
            }

